import { beforeAll, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import { getDatabase } from '../config/database.js'
import { apiTokens } from '../db/schema.js'
import { User } from '../app/Models/User.js'
import app from '../src/app.js'

describe('personal API tokens', () => {
  let http: TestApp
  let user: Awaited<ReturnType<typeof User.first>>

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
    user = await User.first()
  })

  const mint = async (name: string) => {
    const res = await http.post('/profile/tokens').actingAs(user as never).acceptJson().withJson({ name }).send()
    res.assertCreated()
    return (await res.json()) as { id: string; name: string; token: string }
  }

  const call = (method: 'get' | 'post', token: string, body?: unknown) => {
    const req = http[method]('/api/posts').acceptJson().withHeader('Authorization', `Bearer ${token}`)
    return (body ? req.withJson(body) : req).send()
  }

  it('creates tokens, storing only a hash, and authenticates the API', async () => {
    const created = await mint('CI')
    const secret = created.token.split('|')[1]!
    expect(secret.length).toBeGreaterThanOrEqual(16)
    const rows = await getDatabase().select().from(apiTokens)
    expect(JSON.stringify(rows)).not.toContain(secret)

    const list = await call('get', created.token)
    list.assertOk()
    const post = await call('post', created.token, { title: 'T', excerpt: 'E', body: 'B', authorId: 999 })
    post.assertCreated()
    expect(((await post.json()) as { data: { authorId: number } }).data.authorId).toBe((user as { id: number }).id)
    ;(await call('post', created.token, { title: '', excerpt: 'E', body: 'B' })).assertUnprocessable()
  })

  it('rejects bad tokens and revoked tokens', async () => {
    const a = await mint('a')
    const b = await mint('b')
    ;(await call('get', a.token + 'x')).assertUnauthorized()
    ;(await call('get', 'nope')).assertUnauthorized()
    const del = await http.delete(`/profile/tokens/${a.id}`).actingAs(user as never).acceptJson().send()
    del.assertNoContent()
    ;(await call('get', a.token)).assertUnauthorized()
    ;(await call('get', b.token)).assertOk()
    ;(await http.delete(`/profile/tokens/nonexistent`).actingAs(user as never).acceptJson().send()).assertNotFound()
  })

  it('validates names', async () => {
    for (const name of ['', 'x'.repeat(51)]) {
      ;(await http.post('/profile/tokens').actingAs(user as never).acceptJson().withJson({ name }).send()).assertUnprocessable()
    }
  })

  it('limits each token to 60 requests a minute', async () => {
    const a = await mint('rl-a')
    const b = await mint('rl-b')
    for (let i = 0; i < 60; i++) (await call('get', a.token)).assertOk()
    const limited = await call('get', a.token)
    limited.assertStatus(429)
    expect(Number(limited.headers.get('Retry-After'))).toBeLessThanOrEqual(60)
    ;(await call('get', b.token)).assertOk()
  })
})
EOF
